import{_ as t}from"./chunks/01-editor-overview.B6DfPzWc.js";import{_ as o,o as r,c as d,a2 as n}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Introduction and concepts","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md"}'),s={name:"guide/introduction.md"};function a(i,e,c,l,h,m){return r(),d("div",null,[...e[0]||(e[0]=[n('<h1 id="introduction-and-concepts" tabindex="-1">Introduction and concepts <a class="header-anchor" href="#introduction-and-concepts" aria-label="Permalink to &quot;Introduction and concepts&quot;">​</a></h1><p><strong>ReelForge</strong> turns a voice recording and one YAML file into a finished vertical explainer video: 1080×1920 at 30 fps, ready for <strong>TikTok</strong>, <strong>Instagram Reels</strong> and <strong>YouTube Shorts</strong>.</p><p><img src="'+t+'" alt="The ReelForge editor"></p><p>You write what you say, sentence by sentence, and describe what appears on screen and <strong>on which word</strong>. ReelForge animates diagrams, code, tables, charts and titles exactly when you say them, adds word-by-word captions, sound effects and series branding, masters the audio and encodes platform-ready files.</p><h2 id="highlights" tabindex="-1">Highlights <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights&quot;">​</a></h2><ul><li><strong>A real editor, made simple.</strong> Place components on the frame like in a design tool, retime them on a timeline like in a video editor, edit every property in the inspector, with undo, smart guides, a command palette and keyboard shortcuts for everything.</li><li><strong>Timed to your words.</strong> Elements appear on the word that names them. Re-record a sentence and everything after it stays in sync, because animations follow your words, not seconds.</li><li><strong>English and Arabic.</strong> Word-by-word captions in English, and in Arabic with correct right-to-left layout when English terms are mixed in: <code>الـ client</code> stays together and <code>؟</code> lands on the correct side.</li><li><strong>Templates for many sectors.</strong> Industry packs (healthcare, real estate, logistics, education, finance and more) give you ready templates: fill in a few fields and the episode is designed for you.</li><li><strong>Works with AI assistants (optional).</strong> A built-in MCP server and a REST API let Claude, Cursor, Copilot, Codex, Gemini and other clients write scripts, build scenes and check frames for you.</li><li><strong>Animated components</strong> for explainers: nodes and arrows with moving packets, code that types itself, charts, steps and flows, tables, timelines, meters, counters, a phone mock, stamps…</li><li><strong>Professional sound</strong>: procedural sound effects on every hit and transition, voice mastered to −14 LUFS (the platforms&#39; loudness target), effects ducked under the voice.</li><li><strong>Platform-ready output</strong>: an archival master MP4, a share MP4 that fits the upload limit you choose, SRT captions, a contact sheet and a <code>publish.md</code> with your caption, hashtags and pinned comment.</li><li><strong>No AI in the render engine.</strong> Frames are drawn by a deterministic engine and encoded by FFmpeg. It never generates voices or visuals: your voice, your words, your design, consistent every time.</li><li><strong>Optional local helpers.</strong> Speech alignment marks every line and word from your recording, and scene suggestions propose a component for a line. Both run on your computer, and you can always mark cues by ear and design scenes yourself instead.</li><li><strong>Offline and private.</strong> Everything runs on your computer. No account, no subscription, no upload. <code>reelforge align --setup</code> downloads the optional speech models once; after that, everything runs offline.</li><li><strong>Deterministic.</strong> The same inputs always produce the same frames.</li></ul><h2 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Episode</strong></td><td>One video: a folder <code>episodes/&lt;id&gt;/</code> with <code>episode.yaml</code>, your <code>voice.wav</code>, <code>cues.json</code> and the outputs in <code>out/</code>.</td></tr><tr><td><strong>Script line</strong></td><td>One spoken sentence. Lines get ids <code>l1</code>, <code>l2</code>, … in order. Captions are built from them.</td></tr><tr><td><strong>Cue</strong></td><td>The moment a line starts in your recording. Cues come from automatic alignment, from marking by ear, or from an estimate before you record.</td></tr><tr><td><strong>Scene</strong></td><td>A group of elements on screen. A scene starts on a line (<code>at: l3</code>) and ends where the next scene starts.</td></tr><tr><td><strong>Element</strong></td><td>One component placed in a scene, with props, a box (<code>place</code>), and times to enter and exit.</td></tr><tr><td><strong>Component</strong></td><td>A building block such as <code>title</code>, <code>node</code>, <code>arrow</code>, <code>code</code>, <code>bar-chart</code> or <code>steps</code>. Props are strict and listed in the components reference.</td></tr><tr><td><strong>Time expression</strong></td><td>A time written relative to your words: <code>l3</code>, <code>l3.end</code>, <code>l3:&#39;bucket&#39;</code>, <code>@scene.end</code>, plus offsets such as <code>+0.4</code>. Words survive re-recording.</td></tr><tr><td><strong>Theme</strong></td><td>Colors, fonts, sizes and motion tokens in <code>themes/&lt;name&gt;.theme.yaml</code>.</td></tr><tr><td><strong>Preset</strong></td><td>The platform layout (<code>tiktok</code>, <code>reels</code>, <code>shorts</code>): header, stage and caption positions and the platform&#39;s safe zones.</td></tr><tr><td><strong>Pack, template</strong></td><td>An industry pack bundles a theme and templates. A template is an episode with named fields (slots) that you fill in.</td></tr><tr><td><strong>Timeline</strong></td><td>The compiled episode with every time resolved. It is the only contract between the compiler and the renderer, which keeps the output repeatable.</td></tr></tbody></table><h2 id="how-a-video-is-made" tabindex="-1">How a video is made <a class="header-anchor" href="#how-a-video-is-made" aria-label="Permalink to &quot;How a video is made&quot;">​</a></h2><ol><li><strong>Start</strong> from a template (<code>reelforge new &lt;id&gt; --pack &lt;pack&gt; --template &lt;template&gt;</code>), from a blank episode (<code>reelforge new &lt;id&gt;</code>) or from the dashboard.</li><li><strong>Write the script</strong>: one short spoken sentence per line, about 2.3 words per second.</li><li><strong>Design scenes</strong> in the editor or in YAML, with each element entering on the word that names it.</li><li><strong>Record</strong> your voice. <code>reelforge align</code> marks every line and word; you check by ear in Cues mode.</li><li><strong>Review</strong>: every check (overlap, safe zones, text overflow, pacing) has a fix hint.</li><li><strong>Render</strong> and upload the share file with the texts from <code>publish.md</code>.</li></ol><p>The <a href="./quick-start.html">quick start</a> walks through these steps in about ten minutes.</p><h2 id="what-is-in-the-repository" tabindex="-1">What is in the repository <a class="header-anchor" href="#what-is-in-the-repository" aria-label="Permalink to &quot;What is in the repository&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Folder / file</th><th>Contents</th></tr></thead><tbody><tr><td><code>install.bat</code> (<code>install.ps1</code>), <code>install.sh</code></td><td>One-command installers for Windows, macOS and Linux</td></tr><tr><td><code>start.bat</code>, <code>start.sh</code>, <code>ReelForge.command</code></td><td>Open the dashboard</td></tr><tr><td><code>reelforge.cmd</code>, <code>reelforge</code></td><td>The command-line interface</td></tr><tr><td><code>examples/season1/</code></td><td>Nine complete example episodes in English (“System Design”)</td></tr><tr><td><code>examples/season1-arabic/</code></td><td>The same series in Arabic with English technical terms</td></tr><tr><td><code>examples/promo/intro/</code></td><td>A 45-second ReelForge intro video, a showcase of animations</td></tr><tr><td><code>packs/</code></td><td>Industry packs: manifests, templates and example episodes</td></tr><tr><td><code>skills/</code></td><td>Task guides for AI assistants (Agent Skills format)</td></tr><tr><td><code>AGENTS.md</code>, <code>CLAUDE.md</code>, <code>GEMINI.md</code>, …</td><td>Instructions for AI assistants (see <a href="./ai.html">AI integration</a>)</td></tr><tr><td><code>themes/</code>, <code>presets/</code></td><td>Editable visual themes and platform layouts</td></tr><tr><td><code>docs/</code>, <code>documentation/</code></td><td>This documentation (site source, and an offline copy)</td></tr><tr><td><code>packages/</code></td><td>Full TypeScript source code</td></tr><tr><td><code>LICENSE</code>, <code>NOTICE</code>, <code>THIRD-PARTY-NOTICES.md</code></td><td>Apache-2.0 license, notices and third-party credits</td></tr></tbody></table><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Minimum</th><th>Recommended</th></tr></thead><tbody><tr><td>Operating system</td><td>Windows 10, macOS 13, Ubuntu 22.04 (or any recent Linux)</td><td>Windows 11, macOS 14+, Ubuntu 24.04</td></tr><tr><td>CPU / RAM</td><td>4 cores, 8 GB</td><td>8 threads or more, 16 GB (renders scale with cores)</td></tr><tr><td>Disk</td><td>2 GB free (plus ~2 GB temporary space per render)</td><td>SSD</td></tr><tr><td>Software</td><td><strong>Node.js 22 LTS</strong>, <strong>ffmpeg 6+</strong></td><td>installed automatically by the installer where possible</td></tr></tbody></table><p>A 2-minute episode renders in roughly 5–10 minutes on an 8-thread laptop.</p>',16)])])}const f=o(s,[["render",a]]);export{u as __pageData,f as default};
